/**
 * Notion Node - Version 3
 * Discriminator: resource=page, operation=search
 */


interface Credentials {
  notionApi: CredentialReference;
  notionOAuth2Api: CredentialReference;
}

/** Search data sources */
export type NotionV3PageSearchParams = {
  resource: 'page';
  operation: 'search';
  authentication?: 'apiKey' | 'oAuth2' | Expression<string>;
/**
 * Search Text
 */
    text?: string | Expression<string>;
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 50
 */
    limit?: number | Expression<number>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Sort
     * @default {}
     */
    sort?: {
        /** Sort
     */
    sortValue?: {
      /** The direction to sort
       * @default descending
       */
      direction?: 'ascending' | 'descending' | Expression<string>;
      /** The name of the timestamp to sort against
       * @default last_edited_time
       */
      timestamp?: 'last_edited_time' | Expression<string>;
    };
  };
  };
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @builderHint When true, pages under another page or the workspace return only id, name, and url. Database pages also return property_ keys with snake_case names, such as property_status and property_owner. Status values use the status name when present. Rich-text values are strings. People values are arrays of email addresses, with {} for missing emails; handle those entries when mapping to the type the destination expects. Match downstream expressions and verification output fixtures to the returned page type. When false, read the native properties object. Use raw output when you need person names or other native page fields.
 * @default true
 */
    simple?: boolean | Expression<boolean>;
};

export type NotionV3PageSearchOutput = {
  id?: string;
  name?: string;
  url?: string;
};

export type NotionV3PageSearchNode = {
  type: 'n8n-nodes-base.notion';
  version: 3;
  config: NodeConfig<NotionV3PageSearchParams> & { credentials?: Credentials };
  output?: Items<NotionV3PageSearchOutput>;
};